import { LegendItem } from 'pages/pillars/ValueCreation/VolumePages/types';

export interface CountryContributionChartLabel {
  value: string;
  image: string;
  country?: string;
}

export interface CountryContributionChartData {
  data?: number[];
  labels?: CountryContributionChartLabel[];
  legend?: LegendItem[];
}

const getLabelText = (
  label: CountryContributionChartLabel,
  useCountryFallback: boolean,
) => (useCountryFallback ? label.value || label.country || '' : label.value);

export const processBrandAvatarData = (
  chartData: CountryContributionChartData | undefined,
  useCountryFallback = false,
) => {
  if (!Array.isArray(chartData?.labels)) {
    return [];
  }

  return chartData.labels.map((label) => {
    const title = getLabelText(label, useCountryFallback);

    return {
      title,
      mainBrand: { src: label.image, alt: title },
    };
  });
};

export const extractLegends = (
  chartData: CountryContributionChartData | undefined,
  { requireNonEmpty = false }: { requireNonEmpty?: boolean } = {},
): LegendItem[] | undefined => {
  if (!Array.isArray(chartData?.legend)) {
    return undefined;
  }

  if (requireNonEmpty && chartData.legend.length === 0) {
    return undefined;
  }

  return chartData.legend;
};

export const processWaterfallData = (
  chartData: CountryContributionChartData | undefined,
  useCountryFallback = false,
) => {
  const values = chartData?.data || [];
  const labels =
    chartData?.labels?.map((label) =>
      getLabelText(label, useCountryFallback),
    ) || [];

  return { values, labels };
};

export const WATERFALL_LAYOUT = {
  padding: {
    left: 20,
    right: 16,
    top: 49,
    bottom: 0,
  },
  barColors: {
    first: '#C9D1D6',
    last: '#4C5965',
    retained: '#D1A33C',
    negative: '#A20A0A',
    positive: '#49764B',
  },
} as const;
